VALUES (i.[Id], i.[CatalogDescription], i.[CatalogDescriptionEn], i.[CategoryDescription], i.[CategoryDescriptionEn], i.[CreatedBy], i.[CreatedOn], i.[DefaultCheck], i.[ItemDescription], i.[ItemDescriptionEn], i.[MainClassificationDescription], i.[MainClassificationDescriptionEn], i.[MainClassificationId], i.[ServiceType], i.[State], i.[SubjectDescription], i.[SubjectDescriptionEn], i.[Title], i.[TitleDescription], i.[TitleDescriptionEn], i.[TitleEn], i.[UpdatedBy], i.[UpdatedOn])
OUTPUT INSERTED.[RowVersion], i._Position;
